export function doctolibChoicesSvg(lang, kind, mobile = false) {
  if (!['fr', 'en'].includes(lang) || !DOCTOLIB_CHOICES_KINDS.includes(kind) || typeof mobile !== 'boolean') {
    throw new TypeError('Invalid Doctolib choices SVG variant');
  }
  return FIGURES[`${kind}-${lang}-${mobile ? 'mobile' : 'desktop'}`];
}
